const AppState={formData:{},purchasedItems:[],productNames:[]};function sanitize(e){return e?e.replace(/\s+/g," ").trim().replace(/[&<>"']/g,function(e){return({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"})[e]}):""}function getAlphabetIndex(e){let t="",n=e;for(;n>=0;)t=String.fromCharCode(n%26+97)+t,n=Math.floor(n/26)-1;return t}function processForm(){AppState.formData={customer_name:sanitize(document.getElementById("customer_name").value),person_in_charge:sanitize(document.getElementById("person_in_charge").value),line_business:sanitize(document.getElementById("line_business").value),business_scale:document.querySelector('input[name="business_scale"]:checked')?.value,business_relationship:document.querySelector('input[name="business_relationship"]:checked')?.value,payment_info:document.querySelector('input[name="payment_info"]:checked')?.value||"",deal_system:document.querySelector('input[name="deal_system"]:checked')?.value,ideal_price_from:document.querySelector('input[name="ideal_price_from"]:checked')?.value,ideal_price_val:document.getElementById("ideal_price_val").value,competitor_price:sanitize(document.getElementById("competitor_price").value),qty_first:document.getElementById("qty_first").value,qty_avg:document.getElementById("qty_avg").value,qty_max:document.getElementById("qty_max").value}}function getCurrentDateString(){let e=new Date,t=e=>e.toString().padStart(2,"0");return`${t(e.getDate())}-${t(e.getMonth()+1)}-${e.getFullYear()}`}